import{useEffect,useState}from"react";import{createInsurancePlan,getVendorInsurancePlans,getVendorInsuranceQuotes,updateInsuranceQuote}from"../../api/insuranceApi";import{ShieldPlus,Users}from"lucide-react";
const empty={insurerName:"",planName:"",insuranceType:"HEALTH",description:"",coverageSummary:"",sumInsured:1000000,premium:8500,premiumFrequency:"YEARLY",minEntryAge:18,maxEntryAge:65,city:"Bengaluru",benefits:[],exclusions:[],claimProcess:"",claimSettlementInfo:"",documents:[],images:[],featured:false};export default function InsuranceManager(){const[f,setF]=useState(empty),[plans,setPlans]=useState([]),[quotes,setQuotes]=useState([]),[m,setM]=useState("");const load=()=>{getVendorInsurancePlans().then(r=>setPlans(r.data?.data||[]));getVendorInsuranceQuotes().then(r=>setQuotes(r.data?.data||[]))};useEffect(() => { load(); }, []);const submit=async()=>{try{await createInsurancePlan({...f,sumInsured:Number(f.sumInsured),premium:Number(f.premium),minEntryAge:Number(f.minEntryAge),maxEntryAge:Number(f.maxEntryAge)});setM("Insurance plan submitted for admin approval");setF(empty);load()}catch(e){setM(e.response?.data?.message||"Could not save plan")}};const status=async(id,s)=>{try{await updateInsuranceQuote(id,{status:s,note:s==="QUOTE_SHARED"?"Vendor has shared quote details with customer.":"Updated by vendor."});load()}catch(e){setM(e.response?.data?.message||"Could not update quote")}};return <div className="page-shell vendor-bg"><p className="eyebrow">INSURANCE · V25</p><h1 className="page-title">Insurance manager</h1>{m&&<div className="mt-4 rounded-xl bg-slate-900 p-3 text-sm text-white">{m}</div>}<div className="mt-7 grid gap-5 xl:grid-cols-3"><div className="card p-5 xl:col-span-2"><h2 className="section-title"><ShieldPlus size={18} className="inline"/> Add insurance plan</h2><div className="mt-4 grid gap-3 sm:grid-cols-2">{[["Insurer","insurerName"],["Plan name","planName"],["Insurance type","insuranceType"],["City","city"],["Sum insured","sumInsured"],["Premium","premium"],["Frequency","premiumFrequency"],["Min entry age","minEntryAge"],["Max entry age","maxEntryAge"]].map(([l,k])=><label key={k}><span className="label">{l}</span><input className="input" type={k.includes("Age")||k==="sumInsured"||k==="premium"?"number":"text"} value={f[k]} onChange={e=>setF({...f,[k]:e.target.value})}/></label>)}</div><label className="mt-3 block"><span className="label">Description</span><textarea className="input" value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><label className="mt-3 block"><span className="label">Coverage summary</span><textarea className="input" value={f.coverageSummary} onChange={e=>setF({...f,coverageSummary:e.target.value})}/></label><label className="mt-3 block"><span className="label">Benefits (one per line)</span><textarea className="input" value={f.benefits.join("\n")} onChange={e=>setF({...f,benefits:e.target.value.split("\n").filter(Boolean)})}/></label><label className="mt-3 block"><span className="label">Exclusions (one per line)</span><textarea className="input" value={f.exclusions.join("\n")} onChange={e=>setF({...f,exclusions:e.target.value.split("\n").filter(Boolean)})}/></label><button className="btn-primary mt-4" onClick={submit}>Submit plan</button></div><div className="space-y-5"><div className="card p-5"><h2 className="section-title">My plans</h2>{plans.map(x=><div className="mt-3 rounded-xl border p-3" key={x.id}><b>{x.planName}</b><p className="text-xs text-slate-500">{x.insurerName} · {x.status||(!x.approved?"PENDING_APPROVAL":"PUBLISHED")}</p></div>)}</div><div className="card p-5"><h2 className="section-title"><Users size={18} className="inline"/> Quote requests</h2>{quotes.map(x=><div className="mt-3 rounded-xl border p-3" key={x.id}><b>{x.quoteNumber}</b><p className="text-xs text-slate-500">{x.customerName} · {x.city}</p><div className="mt-2 flex flex-wrap gap-2">{x.status==="REQUESTED"&&<><button className="btn-secondary text-xs" onClick={()=>status(x.id,"CONTACTED")}>Contacted</button><button className="btn-primary text-xs" onClick={()=>status(x.id,"QUOTE_SHARED")}>Quote shared</button></>}</div></div>)}</div></div></div></div>}
